part of 'app.dart';
extension NotificationUI on _WorkspaceState {
 Widget notificationBell(){final notifications=data['notifications'] as List? ?? [];final unread=notifications.where((n)=>n['read']!=true).length;return Badge(isLabelVisible:unread>0,label:Text('$unread'),child:IconButton(tooltip:'Notifications',onPressed:()=>showNotifications(),icon:const Icon(Icons.notifications_none,size:22,color:navy)));}
 Future<void> showNotifications()async{final notifications=data['notifications'] as List? ?? [];await showDialog<void>(context:context,builder:(c)=>Dialog(child:ConstrainedBox(constraints:const BoxConstraints(maxWidth:500,maxHeight:600),child:Column(mainAxisSize:MainAxisSize.min,children:[Padding(padding:const EdgeInsets.all(20),child:Row(children:[Expanded(child:text('Your notifications',size:23,weight:FontWeight.w700)),IconButton(tooltip:'Close notifications',onPressed:()=>Navigator.pop(c),icon:const Icon(Icons.close))])),if(notifications.isEmpty)Padding(padding:const EdgeInsets.all(30),child:text('All caught up. Your community updates will appear here.',color:muted)),Flexible(child:ListView(shrinkWrap:true,padding:const EdgeInsets.symmetric(horizontal:20),children:notifications.map((n)=>ListTile(contentPadding:const EdgeInsets.symmetric(vertical:8),leading:Icon(n['kind']=='issue'?Icons.task_alt:Icons.campaign_outlined,color:blue),title:text(n['title'],weight:n['read']==true?FontWeight.normal:FontWeight.w700),subtitle:text('${n['body']}\n${n['at'].toString().substring(0,16).replaceFirst('T',' ')}',size:12,color:muted),onTap:(){Navigator.pop(c);if(n['kind']=='issue'){final issues=data['issues'] as List? ?? [];final found=issues.where((i)=>i['id']==n['related_id']);if(found.isNotEmpty)issueDetails(found.first);}else{setState(()=>page='announcements');}})).toList()))]))));await action(()async{await api.request('/notifications/read',method:'POST',body:{});await refresh();});}
}
